SELECT * FROM (
SELECT p.arxiv_id, p.title, p.published, GROUP_CONCAT(a.name, ', ') AS authors FROM papers p JOIN paper_authors pa ON p.arxiv_id = pa.arxiv_id JOIN authors a ON pa.author_id = a.author_id WHERE LOWER(p.title) LIKE '%debate%' GROUP BY p.arxiv_id, p.title, p.published ORDER BY p.published ASC
) LIMIT 51
